import hashlib,json
from pathlib import Path
root=Path('products/services/fr-boamp-public-docs-link-qa')
source=root/'raw/official-search.json'
raw=source.read_bytes()
data=json.loads(raw)
terms=('audit de liens','liens brisés','liens cassés','migration de site','migration du site','refonte du site','redirections')
def matches(value,path=()):
    if isinstance(value,dict):
        for key,item in value.items():
            yield from matches(item,path+(str(key),))
    elif isinstance(value,list):
        for index,item in enumerate(value):
            yield from matches(item,path+(str(index),))
    elif isinstance(value,str):
        if value.lstrip().startswith(('{','[')):
            try:
                decoded=json.loads(value)
            except ValueError:
                pass
            else:
                yield from matches(decoded,path+('embedded_json',))
                return
        text=' '.join(value.split())
        for term in terms:
            pos=text.casefold().find(term)
            if pos>=0:
                yield {'field':'.'.join(path),'term':term,'excerpt':text[max(0,pos-80):pos+len(term)+120]}
records=data['results']
review=[]
for index,record in enumerate(records):
    hits=list(matches(record))
    review.append({'record_index':index,'notice_id':record.get('idweb'),'publication_date':record.get('dateparution'),'response_deadline':record.get('datelimitereponse'),'exact_phrase_excerpts':hits[:8],'exact_phrase_count':len(hits)})
result={'source_sha256':hashlib.sha256(raw).hexdigest(),'returned_count':len(records),'reported_total':data.get('total_count'),'records':review,'limit':'Phrase excerpts from one saved API page. Confirm scope, deadline and any separately quotable lot from the original buyer notice. The capture alone does not establish filter behavior or market coverage.'}
output=root/'exact-phrase-scope-readback.json'
output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(output.read_text(encoding='utf-8')[:5400])
